#!/usr/bin/env python3
"""Generate dependency-free Pages HTML from localized content and studio components.

Run normally to regenerate; --check detects drift without changing any files.
"""
import json
import sys
from html import escape as e
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
T = json.loads((ROOT / 'content/games.json').read_text())
LANGS = ('en', 'de', 'es')
HOST = 'https://appmonto.com'
STORE = 'https://play.google.com/store/apps/details?id=com.kidlogicloft.happyocto'
PRODUCTS = (('happy-octo-puzzle', 'Happy Octo Puzzle', 'octo'), ('clever-beaver', 'Clever Beaver', 'beaver'), ('closer-look-farm', 'Closer Look: Farm', 'farm'))
OUTPUT = {}


def route(lang, suffix=''):
    return ('/' if lang == 'en' else f'/{lang}/') + suffix


def brand(lang):
    return f'<a class="brand" href="{route(lang)}" aria-label="Appmonto Studio"><img class="brand__mark" src="/assets/img/logo.svg" alt="" width="32" height="32" /><span class="brand__word" aria-hidden="true"></span><span class="brand__sub">Studio</span></a>'


def shell(lang, suffix, title, description, body, schema=None, document=False):
    t = T[lang]
    url = HOST + route(lang, suffix)
    alternate = ''.join(f'<link rel="alternate" hreflang="{x}" href="{HOST}{route(x, suffix)}" />' for x in LANGS)
    alternate += f'<link rel="alternate" hreflang="x-default" href="{HOST}{route("en", suffix)}" />'
    switch = ''.join(f'<a href="{route(x, suffix)}" lang="{x}" hreflang="{x}"' + (' aria-current="page"' if x == lang else '') + f'>{x.upper()}</a>' for x in LANGS)
    structured = json.dumps(schema or {'@context':'https://schema.org','@type':'WebPage','name':title,'url':url,'inLanguage':lang,'publisher':{'@type':'Organization','name':'Appmonto Studio','url':HOST}},ensure_ascii=False).replace('<','\\u003c')
    theme = f'<button class="theme-toggle" type="button" data-theme-toggle data-label-dark="{e(t["theme"][0])}" data-label-light="{e(t["theme"][1])}" aria-label="{e(t["theme"][0])}" aria-pressed="false"><svg class="theme-toggle__sun" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="12" cy="12" r="3.5"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2"/></svg><svg class="theme-toggle__moon" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M20 15.1A8.5 8.5 0 0 1 8.9 4a8.5 8.5 0 1 0 11.1 11.1Z"/></svg></button>'
    image = '/apps/happy-octo-puzzle/banner.png' if suffix == 'apps/happy-octo-puzzle/' else '/assets/img/og.png'
    return f'''<!DOCTYPE html>
<!-- Generated by tools/generate_site.py; edit content/ or the generator. -->
<html lang="{lang}" data-theme="light"><head>
<meta charset="UTF-8" /><meta name="viewport" content="width=device-width, initial-scale=1.0" />
<script>try{{document.documentElement.dataset.theme=localStorage.getItem('appmonto-theme')==='dark'?'dark':'light'}}catch(_){{document.documentElement.dataset.theme='light'}}</script>
<title>{e(title.rstrip("."))} — Appmonto Studio</title><meta name="description" content="{e(description)}" />
<link rel="canonical" href="{url}" />{alternate}
<meta property="og:type" content="website" /><meta property="og:site_name" content="Appmonto Studio" /><meta property="og:title" content="{e(title.rstrip("."))} — Appmonto Studio" /><meta property="og:description" content="{e(description)}" /><meta property="og:url" content="{url}" /><meta property="og:image" content="{HOST}{image}" /><meta property="og:locale" content="{dict(en='en_US',de='de_DE',es='es_ES')[lang]}" /><meta name="twitter:card" content="summary_large_image" />
<meta name="theme-color" content="#F7F6F3" /><link rel="icon" type="image/svg+xml" href="/assets/img/favicon.svg" /><link rel="apple-touch-icon" href="/assets/img/apple-touch-icon.png" />
<link rel="stylesheet" href="/assets/css/site.css" /><script type="application/ld+json">{structured}</script></head>
<body><a class="skip" href="#main">{e(t['skip'])}</a>
<header class="site-header"><div class="container header-inner">{brand(lang)}<nav class="nav" aria-label="{e(t['home'])}"><a href="{route(lang,'games/')}">{e(t['games'])}</a><a href="https://getelia.app">Elia</a><a href="{route(lang,'support/')}">{e(t['support'])}</a></nav><div class="header-tools"><nav class="lang-switch" aria-label="Language">{switch}</nav>{theme}</div></div></header>
<main id="main"{' class="game-document container"' if document else ''}>{body}</main>
<footer class="site-footer"><div class="container footer-inner">{brand(lang)}<nav class="foot-links" aria-label="Footer"><a href="{route(lang,'games/')}">{e(t['games'])}</a><a href="https://getelia.app">Elia</a><a href="{route(lang,'games/privacy/')}">{e(t['privacy'])}</a><a href="{route(lang,'support/')}">{e(t['support'])}</a><a href="/legal/">{e(t['legal'])}</a><a href="/privacy/">{e(t['website'])}</a></nav><small>© <span id="year">2026</span> Appmonto Studio</small></div></footer><script src="/assets/js/site.js" defer></script></body></html>
'''


def cards(lang):
    t=T[lang]
    result=[]
    for slug,name,key in PRODUCTS:
        image='<img class="game-icon" src="/apps/happy-octo-puzzle/icon.png" alt="" width="80" height="80" />' if key=='octo' else ''
        result.append(f'<article class="card" data-accent="kid">{image}<p class="card__meta">{e(t["live"] if key=="octo" else t["coming"])}</p><h3>{e(name)}</h3><p class="card__text">{e(t[key])}</p><p class="card__foot"><a href="{route(lang,"apps/"+slug+"/")}">{e(t["learn"])}: {e(name)} →</a></p></article>')
    return '<div class="cards game-cards">'+''.join(result)+'</div>'


def principles(lang):
    t=T[lang]
    return f'<section id="principles" class="tint"><div class="container"><h2>{e(t["principles_head"][1])}</h2><div class="principles">'+''.join(f'<div class="pr"><h3>{e(h)}</h3><p>{e(p)}</p></div>' for h,p in [(t['noads'],t['about']),(dict(en='Clear pricing',de='Klare Preise',es='Precios claros')[lang],t['pricing']),(dict(en='Offline gameplay',de='Offline spielen',es='Juego sin conexión')[lang],t['offline']),(t['privacy'],t['private'])])+'</div></div></section>'


def add(lang,suffix,title,description,body,**kwargs):
    OUTPUT[route(lang,suffix).lstrip('/')+'index.html']=shell(lang,suffix,title,description,body,**kwargs)


for lang,t in T.items():
    if lang=='en':
        home=(ROOT/'content/home/en.html').read_text()
    else:
        home=f'<section class="hero"><div class="container"><p class="eyebrow">Appmonto Studio</p><h1>{e(t["studio_title"])}</h1><p class="lead">{e(t["studio_intro"])}</p><p class="lead">{e(t["noads"])}</p><a class="btn btn--primary" href="{route(lang,"games/")}">{e(t["games"])}</a></div></section><section id="products"><div class="container"><h2>{e(t["games"])}</h2>{cards(lang)}<article class="card elia-card" data-accent="elia"><h2>Elia</h2><p>{e(t["elia"])}</p><a href="https://getelia.app">getelia.app →</a></article></div></section>'+principles(lang)+f'<section id="studio"><div class="container narrow"><h2>{e(t["about_head"][1])}</h2><p>{e(t["about"])}</p><a href="mailto:hello@appmonto.com">hello@appmonto.com</a></div></section>'
    add(lang,'',t['studio_title'],t['studio_intro'],home,schema={'@context':'https://schema.org','@type':'Organization','name':'Appmonto Studio','alternateName':'Appmonto','url':HOST,'logo':HOST+'/assets/img/logo.svg','email':'hello@appmonto.com','brand':{'@type':'Brand','name':'Elia','url':'https://getelia.app'}})
    games=f'<section class="hero"><div class="container game-hero"><div><p class="eyebrow">{e(t["eyebrow"])}</p><h1>{e(t["hero"])}</h1><p class="lead">{e(t["intro"])}</p></div><img class="game-banner" src="/apps/happy-octo-puzzle/banner.png" width="1024" height="500" alt="Happy Octo Puzzle" /></div></section><section id="apps"><div class="container"><h2>{e(t["apps_head"][1])}</h2><p class="lead">{e(t["apps_head"][2])}</p>{cards(lang)}</div></section>'+principles(lang)+f'<section id="about"><div class="container narrow"><h2>{e(t["about_head"][1])}</h2><p>{e(t["about"])}</p></div></section>'
    add(lang,'games/',t['games'],t['intro'],games)
    for slug,name,key in PRODUCTS:
        suffix='apps/'+slug+'/'
        if key=='octo':
            body=(ROOT/f'content/octo/{lang}.html').read_text()
            schema={'@context':'https://schema.org','@type':'SoftwareApplication','name':name,'description':t['octo'],'applicationCategory':'GameApplication','operatingSystem':'Android','url':HOST+route(lang,suffix),'downloadUrl':STORE,'image':HOST+'/apps/happy-octo-puzzle/banner.png','publisher':{'@type':'Organization','name':'Appmonto Studio','url':HOST}}
        else:
            body=f'<section><p class="eyebrow">{e(t["coming"])}</p><h1>{e(name)}</h1><p class="lead">{e(t[key])}</p>'
            if key=='farm': body+=f'<h2>Closer Look</h2><p>{e(t["series"])}</p><p class="notice">{e(t["planned"])}</p>'
            body+=f'<p>{e(t["noads"])}</p></section>'
            schema=None
        body+=f'<p class="notice"><a href="{route(lang,"games/privacy/")}">{e(t["privacy"])}</a> · <a href="mailto:support@appmonto.com?subject={name.replace(" ","%20").replace(":","%3A")}%20support">{e(t["support"])}: {e(name)}</a></p>'
        add(lang,suffix,name,t[key],body,schema=schema,document=True)
    privacy=f'<section class="legal"><h1>{e(t["privacy"])}</h1><p class="fine">{e(t["updated"])}</p>'+''.join(f'<h2>{e(h)}</h2><p>{e(p)}</p>' for h,p in t['sections'])+f'<p><a href="mailto:support@appmonto.com?subject=Game%20privacy">support@appmonto.com</a> · <a href="/legal/">{e(t["legal"])}</a> · <a href="/privacy/">{e(t["website"])}</a> · <a href="https://policies.google.com/privacy">Google — {e(t["privacy"])}</a></p></section>'
    add(lang,'games/privacy/',t['privacy'],t['sections'][0][1],privacy,document=True)
    support=f'<section><h1>{e(t["support_head"])}</h1><p class="lead">{e(t["contact"])}</p><ul>'+''.join(f'<li><a href="mailto:support@appmonto.com?subject={name.replace(" ","%20").replace(":","%3A")}%20support">{e(name)}</a></li>' for slug,name,key in PRODUCTS)+f'</ul><p><a href="mailto:support@appmonto.com?subject=Appmonto%20games%20support">support@appmonto.com</a></p><p>{e(t["private"])}</p><a href="{route(lang,"games/privacy/")}">{e(t["privacy"])}</a></section>'
    add(lang,'support/',t['support'],t['contact'],support,document=True)

urls=[HOST+'/'+p.removesuffix('index.html') for p in OUTPUT]+[HOST+'/privacy/']
OUTPUT['sitemap.xml']='<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'  <url><loc>{u}</loc></url>\n' for u in urls)+'</urlset>\n'
changed=[]
for name,content in OUTPUT.items():
    path=ROOT/name
    if not path.exists() or path.read_text()!=content:
        changed.append(name)
        if '--check' not in sys.argv:
            path.parent.mkdir(parents=True,exist_ok=True)
            path.write_text(content)
if '--check' in sys.argv and changed:
    sys.exit('Generated files differ: '+', '.join(changed))
print(f'{len(OUTPUT)-1} pages and sitemap '+('verified' if '--check' in sys.argv else 'generated'))
